param([string]$Root='C:\Users\charlie\Documents\ChatGPT\Bowser\benchmarks\results\sidebar-verify\run2-B',[int]$Port=8765)
$ErrorActionPreference='Stop';$listener=[Net.HttpListener]::new();$prefix="http://127.0.0.1:$Port/";$listener.Prefixes.Add($prefix);$listener.Start();Set-Content -LiteralPath (Join-Path $Root 'http-listener-ready.txt') -Value "$PID $prefix" -Encoding ASCII
try { while($listener.IsListening){$ctx=$listener.GetContext();$path=Join-Path $Root ($ctx.Request.Url.AbsolutePath.TrimStart('/'));if($ctx.Request.Url.AbsolutePath -eq '/'){$path=Join-Path $Root 'probe.html'};$entry=[pscustomobject]@{at=(Get-Date -Format o);method=$ctx.Request.HttpMethod;url=$ctx.Request.RawUrl;cookie=$ctx.Request.Headers['Cookie'];agent=$ctx.Request.UserAgent};$entry|ConvertTo-Json -Compress|Add-Content -LiteralPath (Join-Path $Root 'http-requests.jsonl');if(Test-Path -LiteralPath $path){$bytes=[IO.File]::ReadAllBytes($path);$ctx.Response.ContentType=if($path.EndsWith('.html')){'text/html; charset=utf-8'}else{'application/octet-stream'};$ctx.Response.ContentLength64=$bytes.Length;$ctx.Response.OutputStream.Write($bytes,0,$bytes.Length)}else{$ctx.Response.StatusCode=404};$ctx.Response.Close()} } finally {$listener.Stop();$listener.Close()}
